const int sensorPin = A0;
const int ledPin = LED_BUILTIN;
void setup() { pinMode(ledPin, OUTPUT); }
void loop() {
    int raw = analogRead(sensorPin);
    int level = map(raw, 0, 1023, 0, 255);
    analogWrite(ledPin, constrain(level, 0, 255));
}

const int pin = LED_BUILTIN;
void setup() { pinMode(pin, OUTPUT); }
void loop() { analogWrite(pin, 128); delay(500); analogWrite(pin, 0); delay(500); }
